/* 灰度 digital 二进制格式化：直接拷贝 empty.c 生成的二进制字符串 */
void Gray_Digital_Format(void *data, char *buf, int buf_size)
{
    (void)data;
    strncpy(buf, gray_digital_str, buf_size - 1);
    buf[buf_size - 1] = '\0';
}
